description:
Implement `useStableCallback` — a hook that wraps a function and always returns the same reference, but always calls the latest version of the function. Useful for passing to `React.memo` children without breaking memoization.

**Example:**
```tsx
const stableOnChange = useStableCallback(onChange);
// stableOnChange reference never changes, but always calls latest onChange
```

starter_code:
import { useRef, useCallback, useEffect } from 'react';

export function useStableCallback<T extends (...args: any[]) => any>(fn: T): T {
  // your code here
}

test_suite:
test('returns same reference across renders', () => {
  const { result, rerender } = renderHook(({ fn }) => useStableCallback(fn), {
    initialProps: { fn: () => 1 }
  });
  const first = result.current;
  rerender({ fn: () => 2 });
  expect(result.current).toBe(first);
});

test('calls latest version of fn', () => {
  const { result, rerender } = renderHook(({ fn }) => useStableCallback(fn), {
    initialProps: { fn: () => 1 }
  });
  rerender({ fn: () => 99 });
  expect(result.current()).toBe(99);
});

test('passes arguments through', () => {
  const fn = vi.fn((x: number) => x * 2);
  const { result } = renderHook(() => useStableCallback(fn));
  expect(result.current(5)).toBe(10);
});

// __hidden__
test('does not call fn during render', () => {
  const fn = vi.fn();
  renderHook(() => useStableCallback(fn));
  expect(fn).not.toHaveBeenCalled();
});

solution:
import { useRef, useCallback, useEffect } from 'react';

export function useStableCallback<T extends (...args: any[]) => any>(fn: T): T {
  const ref = useRef(fn);
  useEffect(() => { ref.current = fn; });
  return useCallback((...args: any[]) => ref.current(...args), []) as T;
}
